import java.util.*;

class Solution {
    public boolean isRectangleCover(int[][] rectangles) {
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE;
        int maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
        long area = 0;
        Set<Long> oddCorners = new HashSet<>();

        for (int[] rectangle : rectangles) {
            int x1 = rectangle[0], y1 = rectangle[1];
            int x2 = rectangle[2], y2 = rectangle[3];
            if (x1 >= x2 || y1 >= y2) {
                return false;
            }

            minX = Math.min(minX, x1);
            minY = Math.min(minY, y1);
            maxX = Math.max(maxX, x2);
            maxY = Math.max(maxY, y2);
            area += (long) (x2 - x1) * (y2 - y1);

            toggle(oddCorners, pointKey(x1, y1));
            toggle(oddCorners, pointKey(x1, y2));
            toggle(oddCorners, pointKey(x2, y1));
            toggle(oddCorners, pointKey(x2, y2));
        }

        long boundingArea = (long) (maxX - minX) * (maxY - minY);
        if (area != boundingArea || oddCorners.size() != 4) {
            return false;
        }
        return oddCorners.contains(pointKey(minX, minY))
                && oddCorners.contains(pointKey(minX, maxY))
                && oddCorners.contains(pointKey(maxX, minY))
                && oddCorners.contains(pointKey(maxX, maxY));
    }

    private void toggle(Set<Long> corners, long key) {
        if (!corners.add(key)) {
            corners.remove(key);
        }
    }

    private long pointKey(int x, int y) {
        return (((long) x) << 32) ^ (y & 0xffffffffL);
    }
}

