class Solution {
    public boolean isRectangleCover(int[][] rectangles) {
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE;
        int maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
        long area = 0;
        Map<Long, Integer> cornerCounts = new HashMap<>();

        for (int[] rectangle : rectangles) {
            int x1 = rectangle[0], y1 = rectangle[1];
            int x2 = rectangle[2], y2 = rectangle[3];
            if (x1 >= x2 || y1 >= y2) {
                return false;
            }

            minX = Math.min(minX, x1);
            minY = Math.min(minY, y1);
            maxX = Math.max(maxX, x2);
            maxY = Math.max(maxY, y2);
            area += (long) (x2 - x1) * (y2 - y1);

            addCorner(cornerCounts, x1, y1);
            addCorner(cornerCounts, x1, y2);
            addCorner(cornerCounts, x2, y1);
            addCorner(cornerCounts, x2, y2);
        }

        if (area != (long) (maxX - minX) * (maxY - minY)) {
            return false;
        }

        Set<Long> outerCorners = Set.of(
                pointKey(minX, minY), pointKey(minX, maxY),
                pointKey(maxX, minY), pointKey(maxX, maxY));
        int seenOuter = 0;
        for (Map.Entry<Long, Integer> entry : cornerCounts.entrySet()) {
            long point = entry.getKey();
            int count = entry.getValue();
            if (outerCorners.contains(point)) {
                if (count != 1) {
                    return false;
                }
                seenOuter++;
            } else if ((count & 1) == 1) {
                return false;
            }
        }
        return seenOuter == 4;
    }

    private void addCorner(Map<Long, Integer> counts, int x, int y) {
        long key = pointKey(x, y);
        counts.put(key, counts.getOrDefault(key, 0) + 1);
    }

    private long pointKey(int x, int y) {
        return (((long) x) << 32) ^ (y & 0xffffffffL);
    }
}

