class Solution {
    public boolean isRectangleCover(int[][] rectangles) {
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE;
        int maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
        TreeMap<Integer, List<int[]>> events = new TreeMap<>();

        for (int[] rectangle : rectangles) {
            int x1 = rectangle[0], y1 = rectangle[1];
            int x2 = rectangle[2], y2 = rectangle[3];
            if (x1 >= x2 || y1 >= y2) {
                return false;
            }
            minX = Math.min(minX, x1);
            minY = Math.min(minY, y1);
            maxX = Math.max(maxX, x2);
            maxY = Math.max(maxY, y2);
            events.computeIfAbsent(x1, key -> new ArrayList<>()).add(new int[]{1, y1, y2});
            events.computeIfAbsent(x2, key -> new ArrayList<>()).add(new int[]{-1, y1, y2});
        }

        List<int[]> activeIntervals = new ArrayList<>();
        Integer previousX = null;
        for (Map.Entry<Integer, List<int[]>> entry : events.entrySet()) {
            int x = entry.getKey();
            if (previousX != null && previousX < x && !coversExactly(activeIntervals, minY, maxY)) {
                return false;
            }

            for (int[] event : entry.getValue()) {
                if (event[0] == 1) {
                    activeIntervals.add(new int[]{event[1], event[2]});
                } else if (!removeInterval(activeIntervals, event[1], event[2])) {
                    return false;
                }
            }
            previousX = x;
        }

        return activeIntervals.isEmpty() && previousX != null && previousX == maxX;
    }

    private boolean coversExactly(List<int[]> intervals, int minY, int maxY) {
        if (intervals.isEmpty()) {
            return false;
        }
        List<int[]> sorted = new ArrayList<>(intervals);
        sorted.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));

        int expectedStart = minY;
        for (int[] interval : sorted) {
            if (interval[0] != expectedStart || interval[1] <= interval[0]) {
                return false;
            }
            expectedStart = interval[1];
        }
        return expectedStart == maxY;
    }

    private boolean removeInterval(List<int[]> intervals, int y1, int y2) {
        for (int i = 0; i < intervals.size(); i++) {
            int[] interval = intervals.get(i);
            if (interval[0] == y1 && interval[1] == y2) {
                intervals.remove(i);
                return true;
            }
        }
        return false;
    }
}

