class Solution {
    public boolean isRectangleCover(int[][] rectangles) {
        int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE;
        int maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE;
        long area = 0;
        TreeMap<Integer, List<int[]>> leftEdges = new TreeMap<>();
        TreeMap<Integer, List<int[]>> rightEdges = new TreeMap<>();
        TreeSet<Integer> xCoordinates = new TreeSet<>();

        for (int[] rectangle : rectangles) {
            int x1 = rectangle[0], y1 = rectangle[1];
            int x2 = rectangle[2], y2 = rectangle[3];
            if (x1 >= x2 || y1 >= y2) {
                return false;
            }
            minX = Math.min(minX, x1);
            minY = Math.min(minY, y1);
            maxX = Math.max(maxX, x2);
            maxY = Math.max(maxY, y2);
            area += (long) (x2 - x1) * (y2 - y1);
            leftEdges.computeIfAbsent(x1, key -> new ArrayList<>()).add(new int[]{y1, y2});
            rightEdges.computeIfAbsent(x2, key -> new ArrayList<>()).add(new int[]{y1, y2});
            xCoordinates.add(x1);
            xCoordinates.add(x2);
        }

        if (area != (long) (maxX - minX) * (maxY - minY)) {
            return false;
        }

        for (int x : xCoordinates) {
            List<int[]> left = normalize(leftEdges.get(x));
            List<int[]> right = normalize(rightEdges.get(x));
            if (left == null || right == null) {
                return false;
            }
            if (x == minX) {
                if (!right.isEmpty() || !isSingleFullSegment(left, minY, maxY)) {
                    return false;
                }
            } else if (x == maxX) {
                if (!left.isEmpty() || !isSingleFullSegment(right, minY, maxY)) {
                    return false;
                }
            } else if (!sameSegments(left, right)) {
                return false;
            }
        }
        return true;
    }

    private List<int[]> normalize(List<int[]> raw) {
        List<int[]> intervals = new ArrayList<>();
        if (raw == null || raw.isEmpty()) {
            return intervals;
        }
        for (int[] interval : raw) {
            intervals.add(new int[]{interval[0], interval[1]});
        }
        intervals.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));

        List<int[]> merged = new ArrayList<>();
        int start = intervals.get(0)[0];
        int end = intervals.get(0)[1];
        for (int i = 1; i < intervals.size(); i++) {
            int[] interval = intervals.get(i);
            if (interval[0] < end) {
                return null;
            }
            if (interval[0] == end) {
                end = interval[1];
            } else {
                merged.add(new int[]{start, end});
                start = interval[0];
                end = interval[1];
            }
        }
        merged.add(new int[]{start, end});
        return merged;
    }

    private boolean isSingleFullSegment(List<int[]> intervals, int minY, int maxY) {
        return intervals.size() == 1 && intervals.get(0)[0] == minY && intervals.get(0)[1] == maxY;
    }

    private boolean sameSegments(List<int[]> a, List<int[]> b) {
        if (a.size() != b.size()) {
            return false;
        }
        for (int i = 0; i < a.size(); i++) {
            if (a.get(i)[0] != b.get(i)[0] || a.get(i)[1] != b.get(i)[1]) {
                return false;
            }
        }
        return true;
    }
}

